///
/// \file variableinfo.h
/// \brief Declares the description of a simulated OPC UA variable.
///

#pragma once

#include <QString>
#include <QStringList>
#include <QVariant>

///
/// \brief Waveform or sequence the simulator generates for a variable.
///
enum class SimulationFunction { None, Sine, Square, Triangle, Ramp, Random, Step, Toggle, Counter, List };

///
/// \brief How a variable value is generated by the simulator.
///
struct SimulationSettings
{
    /// \brief Waveform; None leaves the value untouched.
    SimulationFunction function = SimulationFunction::None;
    /// \brief Update interval in milliseconds.
    int intervalMs = 1000;
    /// \brief Length of one waveform cycle in milliseconds.
    int periodMs = 10000;
    /// \brief Peak deviation from the offset.
    double amplitude = 0.0;
    /// \brief Centre value of the generated signal.
    double offset = 0.0;
    /// \brief Values List cycles through, as text of the variable's data type.
    QStringList values;
};

///
/// \brief OPC UA alarm the server raises from a variable's value.
///
struct AlarmSettings
{
    /// \brief Whether the variable has an alarm.
    bool enabled = false;
    /// \brief Whether the HighHigh limit applies to a numeric variable.
    bool highHighEnabled = false;
    /// \brief Value at or above which the HighHigh state is active.
    double highHigh = 0.0;
    /// \brief Whether the High limit applies to a numeric variable.
    bool highEnabled = false;
    /// \brief Value at or above which the High state is active.
    double high = 0.0;
    /// \brief Whether the Low limit applies to a numeric variable.
    bool lowEnabled = false;
    /// \brief Value at or below which the Low state is active.
    double low = 0.0;
    /// \brief Whether the LowLow limit applies to a numeric variable.
    bool lowLowEnabled = false;
    /// \brief Value at or below which the LowLow state is active.
    double lowLow = 0.0;
    /// \brief Value of a Boolean variable that keeps its off-normal alarm inactive.
    bool normalValue = false;
    /// \brief Event severity from 1 (lowest) to 1000.
    int severity = 500;

    ///
    /// \brief Compares every field.
    /// \param other Settings to compare with.
    /// \return True when all fields are equal.
    ///
    bool operator==(const AlarmSettings &other) const
    {
        return enabled == other.enabled && highHighEnabled == other.highHighEnabled && highHigh == other.highHigh
            && highEnabled == other.highEnabled && high == other.high && lowEnabled == other.lowEnabled
            && low == other.low && lowLowEnabled == other.lowLowEnabled && lowLow == other.lowLow
            && normalValue == other.normalValue && severity == other.severity;
    }

    ///
    /// \brief Tells whether any field differs.
    /// \param other Settings to compare with.
    /// \return True when a field differs.
    ///
    bool operator!=(const AlarmSettings &other) const
    {
        return !(*this == other);
    }
};

///
/// \brief Describes one variable of an object in the address space.
///
struct VariableInfo
{
    ///
    /// \brief OPC UA value quality.
    ///
    enum class Quality { Good, Uncertain, Bad };

    /// \brief String form of the node identifier.
    QString nodeId;
    /// \brief Display name.
    QString displayName;
    /// \brief Resource name of the icon.
    QString icon;
    /// \brief Current value.
    QVariant value;
    /// \brief Built-in data type name; of the elements for an array.
    QString dataType;
    /// \brief Number of elements of an array variable; 0 for a scalar.
    int arrayLength = 0;
    /// \brief Access level text: "Read", "Write" or "Read/Write".
    QString access;
    /// \brief Quality of the current value.
    Quality quality = Quality::Good;
    /// \brief Value the variable starts with; text typed by the user until it is parsed.
    QVariant initialValue;
    /// \brief Quality the server reports with every value of the variable.
    Quality configuredQuality = Quality::Good;
    /// \brief Simulation that drives the value.
    SimulationSettings simulation;
    /// \brief Whether the properties cannot be edited, e.g. for a model variable of a data type the simulation lacks.
    bool readOnly = false;
    /// \brief Whether an imported model defines the variable, so its name, data type and array length are fixed.
    bool fromModel = false;
    /// \brief Alarm raised from the value.
    AlarmSettings alarm;
    /// \brief Active alarm state, e.g. "High" or "Active"; empty while the alarm is inactive or absent.
    QString alarmState;
};
